precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_texture_1;
uniform sampler2D u_texture_2;

void main() {
    fragColor = clamp(
        texture(u_texture_1, vUv) + texture(u_texture_2, vUv),
        vec4(0.),
        vec4(1.)
    );

}

#version 300 es
#define PI 3.14159
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D input_tex;
uniform vec2 resolution; // resolution
uniform vec3 rotation;  // [0, 0, 0]
uniform vec3 translation; // [0, 0, 1]
uniform vec2 scale; // [1, 1]
uniform vec4 background_color; // color [1, 1, 1, 0]

vec2 rotate(vec2 x, float angle_rad) {
    float cos_val = cos(angle_rad);
    float sin_val = sin(angle_rad);

    return vec2(
        cos_val * x.x - sin_val * x.y,
        sin_val * x.x + cos_val * x.y
    );
}

vec3 rotate3(vec3 v, vec3 rotation) {
    v.yz = rotate(v.yz, rotation.x);
    v.xz = rotate(v.xz, rotation.y);
    v.xy = rotate(v.xy, rotation.z);
    return v;
}

vec2 get_intersection_uv(vec3 ray_direction) {
    // camera facing (0, 0, 1)
    // initial image facing (0, 0, -1)
    vec3 texture_normal = vec3(0.0, 0.0, -1.0);
    vec3 texture_positive_x = vec3(1.0, 0.0, 0.0) * scale.x;
    vec3 texture_positive_y = vec3(0.0, 1.0, 0.0) * scale.y;


    texture_normal = rotate3(texture_normal, rotation);
    texture_positive_x = rotate3(texture_positive_x, rotation);
    texture_positive_y = rotate3(texture_positive_y, rotation);

    float numerator = dot(translation, texture_normal);
    float denominator = dot(ray_direction, texture_normal);
    if (abs(denominator) < 1e-5) {
        return vec2(-1.0);
    }
    float t = numerator / denominator;
    vec3 intersection_point = t * ray_direction;
    vec3 relative_dist = intersection_point - translation;

    float proj_x = dot(relative_dist, texture_positive_x);
    float proj_y = dot(relative_dist, texture_positive_y);

    return vec2(proj_x, proj_y);
}



void main() {
    vec2 aspect = vec2(
        resolution.x / resolution.y,
        1.0
    );

    vec2 uv = (vUv - 0.5) * aspect;

    vec3 ray_direction = normalize(vec3(
        uv,
        1.0
    ));

    vec2 intersection_loc = get_intersection_uv(ray_direction);
    uv = intersection_loc + 0.5;


    if (any(greaterThan(uv, vec2(1.0))) || any(lessThan(uv, vec2(0.0)))) {
        fragColor = clamp(background_color, vec4(0.0), vec4(1.0));
        fragColor.rgb *= fragColor.a;
        return;
    } 

    fragColor = texture(input_tex, uv);
}

#version 300 es
precision mediump float;

uniform sampler2D u_texture; // input
uniform vec3 u_hslAdjust; // H (degrees), S (0-1), L (0-1) — [0, 0, 0]

in vec2 vUv;
out vec4 fragColor;

vec3 rgb2hsl(vec3 color) {
    float maxC = max(max(color.r, color.g), color.b);
    float minC = min(min(color.r, color.g), color.b);
    float delta = maxC - minC;

    float h = 0.0;
    float s = 0.0;
    float l = (maxC + minC) / 2.0;

    if (delta != 0.0) {
        s = l > 0.5 ? delta / (2.0 - maxC - minC) : delta / (maxC + minC);

        if (color.r == maxC) {
            h = (color.g - color.b) / delta + (color.g < color.b ? 6.0 : 0.0);
        } else if (color.g == maxC) {
            h = (color.b - color.r) / delta + 2.0;
        } else {
            h = (color.r - color.g) / delta + 4.0;
        }
        h /= 6.0;
    }

    return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t) {
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
    if (t < 1.0/2.0) return q;
    if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
    return p;
}

vec3 hsl2rgb(vec3 hsl) {
    float h = hsl.x;
    float s = hsl.y;
    float l = hsl.z;

    if (s == 0.0) {
        return vec3(l);
    }

    float q = l < 0.5 ? l * (1.0 + s) : l + s - l * s;
    float p = 2.0 * l - q;
    return vec3(
        hue2rgb(p, q, h + 1.0/3.0),
        hue2rgb(p, q, h),
        hue2rgb(p, q, h - 1.0/3.0)
    );
}

void main() {
    vec4 color = texture(u_texture, vUv);

    vec3 hsl = rgb2hsl(color.rgb);

    hsl.x = mod(hsl.x + u_hslAdjust.x / 360.0, 1.0);
    hsl.y = clamp(hsl.y + u_hslAdjust.y, 0.0, 1.0);
    hsl.z = clamp(hsl.z + u_hslAdjust.z, 0.0, 1.0);

    fragColor = vec4(hsl2rgb(hsl), color.a);
}

#version 300 es
precision highp float;

uniform float u_time; // time
uniform vec2 u_resolution; // resolution
uniform float u_speed; // [0, 100, 2]
uniform float u_period; // [0, 100, 2]
uniform float u_amplitude; // [0, 100, 2]

in vec2 vUv;
out vec4 fragColor;

void main() {
    vec2 uv = vec2(vUv.x * 2.0 - 1.0, (1.0 - vUv.y) * 2.0 - 1.0);
    float aspect = u_resolution.x / u_resolution.y;
    uv.x *= aspect;

    float brightness = sin(uv.x * u_period + u_time * u_speed) * u_amplitude;
    fragColor = vec4(vec3(brightness + 1.0) * 0.5, 1.0);
}

#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_input_tex;
uniform float u_blur_dist; // [0, 1, 0.1]
uniform vec2 u_resolution; // resolution
uniform float u_angle; // [0, 10, 0]
uniform float u_blur_sample_count; // [2, 50, 5]
uniform float u_start_offset; // [0, 1, 0.5]


mat2 rotate2D(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(
        c, -s, 
        s,  c  
    );
}

void main() {
    vec2 aspect = vec2(
        u_resolution.x / u_resolution.y,
        1.0
    );

    vec2 uv = vUv * aspect;

    mat2 rot_mat = rotate2D(u_angle);
    mat2 inv_rot_mat = rotate2D(-u_angle);
    vec2 rotated_uv = rot_mat * uv;

    int count = int(floor(u_blur_sample_count));

    vec4 result = vec4(0.0);

    float offset_bias = u_blur_dist * u_start_offset;

    for (int i = 0; i < count; i++) {
        float offset = float(i) / float(count) * u_blur_dist - offset_bias;
        vec2 target_pos = rotated_uv + vec2(offset, 0.0);

        result += texture(
            u_input_tex,
            (inv_rot_mat * target_pos) / aspect
        );
    }

    fragColor = result / float(count);
}

